PAGE_TRANSLATIONS["contact/"]["nl"]["Message"] = "Bericht"

def route_url(route: str) -> str:
    return SITE + "/" + route

def alternates(fr_route: str) -> str:
    en_route, nl_route = PAGES[fr_route]["en"], PAGES[fr_route]["nl"]
    return "\n".join([
        f'    <link rel="alternate" hreflang="fr" href="{route_url(fr_route)}">',
        f'    <link rel="alternate" hreflang="en" href="{route_url(en_route)}">',
        f'    <link rel="alternate" hreflang="nl" href="{route_url(nl_route)}">',
        f'    <link rel="alternate" hreflang="x-default" href="{route_url(fr_route)}">',
    ])

def language_switcher(fr_route: str, locale: str) -> str:
    routes = {"fr": fr_route, "en": PAGES[fr_route]["en"], "nl": PAGES[fr_route]["nl"]}
    label = {"fr":"Choisir la langue", "en":"Choose language", "nl":"Taal kiezen"}[locale]
    links=[]
    for code in ("fr","en","nl"):
        current=' aria-current="true"' if code == locale else ""
        links.append(f'<a href="{TEST_BASE}{routes[code]}" lang="{code}" hreflang="{code}"{current}>{code.upper()}</a>')
    return f'<nav class="language-switcher" aria-label="{label}">' + "".join(links) + "</nav>"

def replace_local_url(value: str, fr_route: str, locale: str) -> str:
    if value.startswith(TEST_BASE):
        return value
    if value.startswith(("http:", "https:", "mailto:", "tel:", "#", "data:")):
        return value
    anchor = ""
    if "#" in value:
        value, anchor = value.split("#", 1); anchor = "#" + anchor
    source_dir = fr_route
    resolved = posixpath.normpath(posixpath.join("/" + source_dir, value)).lstrip("/")
    if value.endswith("/") and resolved and not resolved.endswith("/"):
        resolved += "/"
    if resolved == ".": resolved = ""
    target = PAGES.get(resolved, {}).get(locale, resolved)
    return TEST_BASE + target + anchor

def localize_urls(text: str, fr_route: str, locale: str) -> str:
    attr = re.compile(r'(?P<name>href|src|action)="(?P<value>[^"]+)"')
    text = attr.sub(lambda m: f'{m.group("name")}="{replace_local_url(m.group("value"), fr_route, locale)}"', text)
    def srcset(match: re.Match[str]) -> str:
        values=[]
        for item in match.group(1).split(","):
            bits=item.strip().split()
            bits[0]=replace_local_url(bits[0], fr_route, locale)
            values.append(" ".join(bits))
        return 'srcset="' + ", ".join(values) + '"'
    return re.sub(r'srcset="([^"]+)"', srcset, text)

def add_language_ui(text: str, fr_route: str, locale: str) -> str:
    text = re.sub(r'\n\s*<link rel="alternate" hreflang="(?:fr|en|nl|x-default)" href="[^"]+">', '', text)
    text = re.sub(r'<html lang="fr"', f'<html lang="{locale}"', text, count=1)
    text = re.sub(r'<meta property="og:locale" content="[^"]+">', f'<meta property="og:locale" content="{locale}_{"GB" if locale=="en" else "BE"}">', text, count=1)
    canonical = route_url(fr_route if locale == "fr" else PAGES[fr_route][locale])
    text = re.sub(r'<link rel="canonical" href="[^"]+">', f'<link rel="canonical" href="{canonical}">\n{alternates(fr_route)}', text, count=1)
    text = re.sub(r'<meta property="og:url" content="[^"]+">', f'<meta property="og:url" content="{canonical}">', text, count=1)
    def structured_data(match: re.Match[str]) -> str:
        block = match.group(0).replace('https://edubrussels.org/bred-test/', 'https://edubrussels.org/')
        if locale != "fr":
            for source_route, localized_routes in sorted(PAGES.items(), key=lambda item: len(item[0]), reverse=True):
                source_url, localized_url = route_url(source_route), route_url(localized_routes[locale])
                if source_route:
                    block = block.replace(source_url, localized_url)
                else:
                    block = block.replace(f'"{source_url}"', f'"{localized_url}"')
        return block
    text = re.sub(r'<script type="application/ld\+json">.*?</script>', structured_data, text, flags=re.DOTALL)
    switcher = language_switcher(fr_route, locale)
    text = re.sub(r'<nav class="language-switcher".*?</nav>', '', text, count=1)
    text = re.sub(r'(</ul>)(\s*)(<a class="button button-primary nav-cta")', rf'\1\n                {switcher}\n                \3', text, count=1)
    open_label={"fr":"Ouvrir le menu","en":"Open menu","nl":"Menu openen"}[locale]
    close_label={"fr":"Fermer le menu","en":"Close menu","nl":"Menu sluiten"}[locale]
    text=re.sub(r'(<button class="menu-toggle"[^>]*?)\sdata-open-label="[^"]*"\sdata-close-label="[^"]*"', r'\1', text, count=1)
    text=text.replace(' data-menu-toggle>', f' data-open-label="{open_label}" data-close-label="{close_label}" data-menu-toggle>', 1)
    if 'data-contact-form' in text:
        text = re.sub(r'\s*<input type="hidden" name="language" value="[^"]+">', '', text)
        text = text.replace('<input type="hidden" name="form_duration"', f'<input type="hidden" name="language" value="{locale}">\n                        <input type="hidden" name="form_duration"', 1)
    return text

def update_french_pages() -> None:
    for fr_route in PAGES:
        source = ROOT / fr_route / "index.html" if fr_route else ROOT / "index.html"
        text = source.read_text(encoding="utf-8")
        text = re.sub(r'\n\s*<link rel="alternate" hreflang="(?:fr|en|nl|x-default)" href="[^"]+">', '', text)
        text=re.sub(r'https://edubrussels\.org/bred-test/assets/', 'https://edubrussels.org/assets/', text)
        text=text.replace('https://edubrussels.org/bred-test/', 'https://edubrussels.org/')
        if 'instagram.com/bredassociation' not in text:
            instagram = ('<a class="footer-social" href="https://www.instagram.com/bredassociation" '
                         'target="_blank" rel="noopener noreferrer"><svg viewBox="0 0 24 24" '
                         'aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="5"></rect>'
                         '<circle cx="12" cy="12" r="4"></circle><circle cx="17.4" cy="6.6" r=".8" '
                         'fill="currentColor" stroke="none"></circle></svg>Instagram de BRED'
                         '<span class="visually-hidden"> — nouvel onglet</span></a>')
            text = text.replace('<p>Bruxelles, Belgique</p>', f'<p>Bruxelles, Belgique</p>{instagram}', 1)
        text=add_language_ui(text, fr_route, "fr")
        if 'data-contact-form' in text and 'name="language"' not in text:
            text=text.replace('<input type="hidden" name="form_duration"', '<input type="hidden" name="language" value="fr">\n                        <input type="hidden" name="form_duration"', 1)
        source.write_text(text, encoding="utf-8", newline="\n")

def translate(text: str, fr_route: str, locale: str) -> str:
    mapping = {}
    mapping.update(COMMON[locale])
    mapping.update(TRANSLATIONS.get(fr_route, {}).get(locale, {}))
    mapping.update(PAGE_TRANSLATIONS.get(fr_route, {}).get(locale, {}))
    pattern = re.compile("|".join(re.escape(source) for source in sorted(mapping, key=len, reverse=True)))
    return pattern.sub(lambda match: mapping[match.group(0)], text)

def generate() -> None:
    update_french_pages()
    for fr_route, localized in PAGES.items():
        source = ROOT / fr_route / "index.html" if fr_route else ROOT / "index.html"
        original = source.read_text(encoding="utf-8")
        for locale, target_route in localized.items():
            output = translate(original, fr_route, locale)
            output = add_language_ui(output, fr_route, locale)
            output = localize_urls(output, fr_route, locale)
            destination = ROOT / target_route / "index.html"
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_text(output, encoding="utf-8", newline="\n")

if __name__ == "__main__":
    generate()
